// Validate reference data
const ref = $input.first().json.reference;

if (!ref) {
  throw new Error('Reference data is required');
}

if (!ref.title) {
  throw new Error('Title is required');
}

if (!ref.url && !ref.doi) {
  throw new Error('Either URL or DOI is required');
}

if (!ref.source_type) {
  throw new Error('Source type is required');
}

const validSourceTypes = ['academic', 'governmental', 'international_org', 'news'];
if (!validSourceTypes.includes(ref.source_type)) {
  throw new Error(`Invalid source_type. Must be one of: ${validSourceTypes.join(', ')}`);
}

// Generate citations
const authors = ref.authors || 'Unknown Author';
const year = ref.publication_date 
  ? new Date(ref.publication_date).getFullYear() 
  : 'n.d.';
const title = ref.title;
const source = ref.source_name || '';
const url = ref.url || '';
const doi = ref.doi || '';
const accessed = new Date().toLocaleDateString('en-US', {
  year: 'numeric', month: 'long', day: 'numeric'
});
const accessedHarvard = new Date().toLocaleDateString('en-GB', {
  day: 'numeric', month: 'long', year: 'numeric'
});

// Generate APA citation
let citationAPA;
if (ref.source_type === 'academic') {
  citationAPA = `${authors} (${year}). ${title}. ${source}. ${doi ? 'https://doi.org/' + doi : url}`;
} else if (ref.source_type === 'news') {
  citationAPA = `${authors} (${year}). ${title}. ${source}. Retrieved ${accessed}, from ${url}`;
} else {
  citationAPA = `${authors} (${year}). ${title}. ${source}. Retrieved from ${url}`;
}

// Generate Harvard citation
const citationHarvard = `${authors}, ${year}. ${title}. [online] ${source}. Available at: ${url} [Accessed ${accessedHarvard}].`;

return {
  json: {
    ...ref,
    citation_apa: citationAPA,
    citation_harvard: citationHarvard,
    crime_type: ref.crime_type ? (Array.isArray(ref.crime_type) ? ref.crime_type : [ref.crime_type]) : null,
    region: ref.region ? (Array.isArray(ref.region) ? ref.region : [ref.region]) : null,
    keywords: ref.keywords ? (Array.isArray(ref.keywords) ? ref.keywords : [ref.keywords]) : null
  }
};

