return {
  json: {
    success: true,
    message: 'Reference already exists in database',
    duplicate: true,
    existing_id: $input.first().json[0]?.id
  }
};

return {
  json: {
    success: true,
    message: 'Reference added successfully',
    reference: $input.first().json[0]
  }
};

// Build search query based on parameters
const params = $input.first().json;

let conditions = [];
let queryParams = [];
let paramIndex = 1;

if (params.search_text) {
  conditions.push(`to_tsvector('english', title || ' ' || COALESCE(abstract, '')) @@ plainto_tsquery('english', $${paramIndex})`);
  queryParams.push(params.search_text);
  paramIndex++;
}

if (params.source_type) {
  conditions.push(`source_type = $${paramIndex}::source_type_enum`);
  queryParams.push(params.source_type);
  paramIndex++;
}

if (params.crime_types && params.crime_types.length > 0) {
  conditions.push(`crime_type && $${paramIndex}::crime_type_enum[]`);
  queryParams.push('{' + params.crime_types.join(',') + '}');
  paramIndex++;
}

if (params.regions && params.regions.length > 0) {
  conditions.push(`region && $${paramIndex}::region_enum[]`);
  queryParams.push('{' + params.regions.join(',') + '}');
  paramIndex++;
}

if (params.date_from) {
  conditions.push(`publication_date >= $${paramIndex}::date`);
  queryParams.push(params.date_from);
  paramIndex++;
}

if (params.date_to) {
  conditions.push(`publication_date <= $${paramIndex}::date`);
  queryParams.push(params.date_to);
  paramIndex++;
}

const whereClause = conditions.length > 0 ? 'WHERE ' + conditions.join(' AND ') : '';
const limit = params.limit || 100;

const query = `
  SELECT 
    id, title, title_ar, authors, publication_date,
    source_type, source_name, url, doi,
    crime_type, geographical_scope, region,
    language, abstract, abstract_ar, keywords,
    citation_apa, citation_harvard, relevance_score,
    date_added, last_accessed
  FROM criminal_references
  ${whereClause}
  ORDER BY relevance_score DESC NULLS LAST, publication_date DESC NULLS LAST
  LIMIT ${limit}
`;

return {
  json: {
    query,
    params: queryParams
  }
};

const results = $input.first().json;

return {
  json: {
    success: true,
    count: Array.isArray(results) ? results.length : 0,
    references: Array.isArray(results) ? results : []
  }
};

const updated = $input.first().json;

return {
  json: {
    success: true,
    message: 'Access timestamps updated',
    updated_count: Array.isArray(updated) ? updated.length : 0
  }
};

const stats = $input.first().json[0];

return {
  json: {
    success: true,
    statistics: {
      total_references: stats.total_references,
      by_source_type: stats.by_source_type,
      by_crime_type: stats.by_crime_type,
      by_region: stats.by_region,
      by_year: stats.by_year,
      recent_additions_30_days: stats.recent_additions,
      most_accessed: stats.most_accessed
    }
  }
};

// Build export query
const params = $input.first().json;
const format = params.format || 'apa'; // 'apa' or 'harvard'
const sourceType = params.source_type;
const crimeTypes = params.crime_types;
const regions = params.regions;

let conditions = [];

if (sourceType) {
  conditions.push(`source_type = '${sourceType}'::source_type_enum`);
}

if (crimeTypes && crimeTypes.length > 0) {
  conditions.push(`crime_type && '{${crimeTypes.join(',')}}'::crime_type_enum[]`);
}

if (regions && regions.length > 0) {
  conditions.push(`region && '{${regions.join(',')}}'::region_enum[]`);
}

const whereClause = conditions.length > 0 ? 'WHERE ' + conditions.join(' AND ') : '';

const citationField = format === 'harvard' ? 'citation_harvard' : 'citation_apa';

const query = `
  SELECT 
    id, title, title_ar, authors, publication_date,
    source_type, ${citationField} as citation
  FROM criminal_references
  ${whereClause}
  ORDER BY 
    CASE source_type 
      WHEN 'academic' THEN 1 
      WHEN 'governmental' THEN 2 
      WHEN 'international_org' THEN 3 
      ELSE 4 
    END,
    authors ASC NULLS LAST,
    publication_date DESC NULLS LAST
`;

return {
  json: {
    query,
    format
  }
};

const references = $input.first().json;
const format = $('Build Export Query').item.json.format;

// Group by source type
const grouped = {
  academic: [],
  governmental: [],
  international_org: [],
  news: []
};

if (Array.isArray(references)) {
  references.forEach(ref => {
    if (grouped[ref.source_type]) {
      grouped[ref.source_type].push(ref.citation);
    }
  });
}

// Format bibliography
let bibliography = '';
const formatName = format === 'harvard' ? 'Harvard' : 'APA';

bibliography += `قائمة المراجع (${formatName})\n`;
bibliography += '═'.repeat(50) + '\n\n';

if (grouped.academic.length > 0) {
  bibliography += 'أ. المصادر الأكاديمية:\n';
  bibliography += '─'.repeat(30) + '\n';
  grouped.academic.forEach((cite, i) => {
    bibliography += `${i + 1}. ${cite}\n\n`;
  });
}

if (grouped.governmental.length > 0) {
  bibliography += '\nب. المصادر الحكومية:\n';
  bibliography += '─'.repeat(30) + '\n';
  grouped.governmental.forEach((cite, i) => {
    bibliography += `${i + 1}. ${cite}\n\n`;
  });
}

if (grouped.international_org.length > 0) {
  bibliography += '\nج. مصادر المنظمات الدولية:\n';
  bibliography += '─'.repeat(30) + '\n';
  grouped.international_org.forEach((cite, i) => {
    bibliography += `${i + 1}. ${cite}\n\n`;
  });
}

if (grouped.news.length > 0) {
  bibliography += '\nد. المصادر الإخبارية:\n';
  bibliography += '─'.repeat(30) + '\n';
  grouped.news.forEach((cite, i) => {
    bibliography += `${i + 1}. ${cite}\n\n`;
  });
}

return {
  json: {
    success: true,
    format: format,
    total_references: Array.isArray(references) ? references.length : 0,
    bibliography: bibliography,
    grouped_counts: {
      academic: grouped.academic.length,
      governmental: grouped.governmental.length,
      international_org: grouped.international_org.length,
      news: grouped.news.length
    }
  }
};

// Process batch of references
const references = $input.first().json.references;

if (!Array.isArray(references)) {
  throw new Error('References must be an array');
}

const validSourceTypes = ['academic', 'governmental', 'international_org', 'news'];
const processedRefs = [];

for (const ref of references) {
  if (!ref.title) continue;
  if (!ref.url && !ref.doi) continue;
  if (!validSourceTypes.includes(ref.source_type)) continue;

  // Generate citations
  const authors = ref.authors || 'Unknown Author';
  const year = ref.publication_date 
    ? new Date(ref.publication_date).getFullYear() 
    : 'n.d.';
  const title = ref.title;
  const source = ref.source_name || '';
  const url = ref.url || '';
  const doi = ref.doi || '';
  const accessed = new Date().toLocaleDateString('en-US', {
    year: 'numeric', month: 'long', day: 'numeric'
  });
  const accessedHarvard = new Date().toLocaleDateString('en-GB', {
    day: 'numeric', month: 'long', year: 'numeric'
  });

  let citationAPA;
  if (ref.source_type === 'academic') {
    citationAPA = `${authors} (${year}). ${title}. ${source}. ${doi ? 'https://doi.org/' + doi : url}`;
  } else if (ref.source_type === 'news') {
    citationAPA = `${authors} (${year}). ${title}. ${source}. Retrieved ${accessed}, from ${url}`;
  } else {
    citationAPA = `${authors} (${year}). ${title}. ${source}. Retrieved from ${url}`;
  }

  const citationHarvard = `${authors}, ${year}. ${title}. [online] ${source}. Available at: ${url} [Accessed ${accessedHarvard}].`;

  processedRefs.push({
    ...ref,
    citation_apa: citationAPA,
    citation_harvard: citationHarvard,
    crime_type: ref.crime_type ? (Array.isArray(ref.crime_type) ? ref.crime_type : [ref.crime_type]) : null,
    region: ref.region ? (Array.isArray(ref.region) ? ref.region : [ref.region]) : null,
    keywords: ref.keywords ? (Array.isArray(ref.keywords) ? ref.keywords : [ref.keywords]) : null
  });
}

return processedRefs.map(ref => ({ json: ref }));

const items = $input.all();
const insertedIds = items.map(item => item.json[0]?.id).filter(id => id);

return {
  json: {
    success: true,
    message: 'Batch references processed',
    inserted_count: insertedIds.length,
    inserted_ids: insertedIds
  }
};

return {
  json: {
    success: false,
    error: 'Unknown operation',
    message: 'Valid operations: ADD_REFERENCE, SEARCH_REFERENCES, UPDATE_LAST_ACCESSED, GET_STATISTICS, EXPORT_REFERENCES, ADD_BATCH_REFERENCES'
  }
};
